    # This is a simple implementation for BFS pathfinding using collections.deque instead of list for faster append/pop operations
    from collections import deque

    # Use a visited set to keep track of nodes already expanded
    visited = set()

    # Use a queue for BFS
    queue = deque([(start, [start])])  # Node and path taken

    while(queue):
        (node, path) = queue.pop()
        if node not in visited:
            neighbors = graph.get(node, [])  # Get neighbors for given node
            for neighbor in neighbors:
                total_path = path + [neighbor]  # Construct new path
                if neighbor == goal:
                    return total_path
                else:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.appendleft((neighbor, total_path))
