def find_path(graph, start, goal):
    """
    Implement Dijkstra's algorithm for unweighted graphs. Dijkstra does shortest 
    path with unweighted graph, meaning any edges are considered to have zero cost.
    If the goal is to find longest possible path (with unweighted edges), consider the 
    opposite (i.e., negative weights). 
    """
    def dijkstra_shortest_path(graph, start, goal):
        shortest_paths = {}
        previous_nodes = {}
        unseen_nodes = graph

        distance = {}

        for node in unseen_nodes:
            distance[node] = [float('infinity'), None]
        distance[start][0] = 0

        while unseen_nodes:
            smallest_node = None
            for node in unseen_nodes:
                if smallest_node is None:
                    smallest_node = node
                elif distance[node] < distance[smallest_node]:
                    smallest_node = node

            neighbors = graph.get(smallest_node, [])
            for neighbor in neighbors:
                path_distance = distance[smallest_node][0] + 1
                if path_distance < distance[neighbor][0]:
                    shortest_paths[neighbor] = [path_distance, smallest_node]
                    distance[neighbor] = path_distance
            unseen_nodes.pop(smallest_node)

        full_path = []
        while goal is not None:
            full_path.insert(0, goal)
            goal = previous_nodes[goal]
        return full_path if len(full_path) > 0 else None

    return dijkstra_shortest_path(graph, start, goal)

