    def _depth_first_search(graph, curr, goal, path, paths_found):
        if curr == goal:
            return True

        path.append(curr)
        if not path:
            path.append(curr)

        for next_node in graph.get(curr, []):
            if path and path and path[0] == next_node:
                continue
            paths_new = [_p[:] + [next_node] for _p in paths_found]
            found = _depth_first_search(
                graph=graph,
                curr=next_node,
                goal=goal,
                path=path,
                paths_found=paths_new  # Passing new list of possible paths
            )
            if found:
                return True

        return None
    paths_found = [start]
    while paths_found:
        new_paths_found = []
        for path in paths_found:
            result_path = _depth_first_search(graph, start, goal, [], new_paths_found)
            if not result_path:
                new_paths_found.append(path.pop(0))

        if not new_paths_found:
            break
        paths_found = new_paths_found

    paths_found = [path[::-1] for path in paths_found]  # Reverse path to get the start to goal order
    return paths_found[0] if len(paths_found[0]) > 0 else None
