    visited = {key: set([]) for key in graph.keys()} # Keep track of visited nodes
    queue.put(start)
    while not queue.empty():
        node = queue.get_nowait()
        if node == goal:
            # reconstruct path from 'goal' node backward
            return visited[node]
        if node in graph:
            next_nodes = graph[node] 
            for n in next_nodes:
                if n in visited.keys():
                    if node in visited.get(n)[::-1]:   
                        queue.cancelled_nowait()  # cancel previous enqueued tasks that should not happen now
                        queue.get_nowait()   # clear queue to avoid duplicates
                        continue
                visited[n].add(node)
                if n != goal: 
                    queue.put(n)
    return None

