def find_path(graph, start, goal):
    """
    Searches for a sequence of nodes that forms a path from the start vertex to the goal vertex
    within a given directed graph of adjacent vertices.

    :param graph: Dictionary where keys are vertices and values are lists of neighboring vertices.
    :param start: The starting vertex of the path. Should be one of graph keys.
    :param goal: The vertex to find in the graph. Should be one of graph keys.
    :return: A list of vertices that forms a path from start to goal, or None if there is no such path.
    """
    def search(path, next_vertex):
        if visited[next_vertex]:
            return None
        if next_vertex == goal:
            return path
        visited[next_vertex] = True
        for new_vertex in graph.get(next_vertex, []):
            result = search(path + [new_vertex], new_vertex)
            if result:
                return result
        return None

    if start not in graph:
        return None
    if goal not in graph:
        return None

    visited = {vertex: False for vertex in graph}

    return search([start], start)


