        visited.add(node)  # add the current node as visited

        for next_node in graph[node]:  # explore adjacent nodes 
            if next_node in path:
                # If next node is in path, return the concatenation of path to current path from start to next node, including the current node
                return path[next_node] + [next_node]
            else:
                if next_node not in visited:
                    # If next_node is not in path and is visited add it as part of new path.
                    path[next_node] = path[node] + [next_node]
                    search(next_node)

        return None

    if search(start) is None:
        return None
    return path[goal]
